BEGIN;
CREATE TABLE ai_vendor_invoice_near_duplicate_finding(
  ai_vendor_invoice_near_duplicate_finding_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenant(tenant_id),entity_id uuid NOT NULL,accounting_period_id uuid NOT NULL,policy_snapshot_id uuid NOT NULL,policy_snapshot_hash text NOT NULL CHECK(policy_snapshot_hash~'^sha256:[0-9a-f]{64}$'),finding_hash text NOT NULL CHECK(finding_hash~'^sha256:[0-9a-f]{64}$'),finding jsonb NOT NULL,status text NOT NULL DEFAULT 'OPEN' CHECK(status='OPEN'),created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  UNIQUE(tenant_id,entity_id,ai_vendor_invoice_near_duplicate_finding_id),UNIQUE(tenant_id,entity_id,finding_hash),FOREIGN KEY(tenant_id,entity_id) REFERENCES entity(tenant_id,entity_id),FOREIGN KEY(tenant_id,entity_id,accounting_period_id) REFERENCES accounting_period(tenant_id,entity_id,period_id),FOREIGN KEY(tenant_id,policy_snapshot_id) REFERENCES setting_snapshot(tenant_id,setting_snapshot_id),CHECK(finding->>'schema_version'='AI_VENDOR_INVOICE_NEAR_DUPLICATE_FINDING_V1'),CHECK(finding->'action_flags'='{"can_create_draft":false,"can_review":false,"can_approve":false,"can_post":false}'::jsonb)
);
CREATE TABLE ai_vendor_invoice_near_duplicate_source(
  tenant_id uuid NOT NULL,entity_id uuid NOT NULL,ai_vendor_invoice_near_duplicate_finding_id uuid NOT NULL,source_ordinal smallint NOT NULL CHECK(source_ordinal IN(1,2)),accounting_period_id uuid NOT NULL,source_document_id uuid NOT NULL,source_document_line_id uuid NOT NULL,source_payload_hash text NOT NULL CHECK(source_payload_hash~'^sha256:[0-9a-f]{64}$'),source_line_hash text NOT NULL CHECK(source_line_hash~'^sha256:[0-9a-f]{64}$'),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(tenant_id,entity_id,ai_vendor_invoice_near_duplicate_finding_id,source_ordinal),UNIQUE(tenant_id,entity_id,ai_vendor_invoice_near_duplicate_finding_id,source_document_line_id),FOREIGN KEY(tenant_id,entity_id,ai_vendor_invoice_near_duplicate_finding_id) REFERENCES ai_vendor_invoice_near_duplicate_finding(tenant_id,entity_id,ai_vendor_invoice_near_duplicate_finding_id),FOREIGN KEY(tenant_id,entity_id,accounting_period_id) REFERENCES accounting_period(tenant_id,entity_id,period_id),FOREIGN KEY(tenant_id,entity_id,source_document_id) REFERENCES source_document(tenant_id,entity_id,source_document_id),FOREIGN KEY(tenant_id,entity_id,source_document_line_id) REFERENCES source_document_line(tenant_id,entity_id,source_document_line_id)
);
ALTER TABLE ai_vendor_invoice_near_duplicate_finding ENABLE ROW LEVEL SECURITY;ALTER TABLE ai_vendor_invoice_near_duplicate_source ENABLE ROW LEVEL SECURITY;
CREATE POLICY ai_vendor_invoice_near_duplicate_finding_scope ON ai_vendor_invoice_near_duplicate_finding USING(tenant_id=refs_current_tenant() AND refs_entity_allowed(entity_id)) WITH CHECK(tenant_id=refs_current_tenant() AND refs_entity_allowed(entity_id));
CREATE POLICY ai_vendor_invoice_near_duplicate_source_scope ON ai_vendor_invoice_near_duplicate_source USING(tenant_id=refs_current_tenant() AND refs_entity_allowed(entity_id)) WITH CHECK(tenant_id=refs_current_tenant() AND refs_entity_allowed(entity_id));
CREATE TRIGGER ai_vendor_invoice_near_duplicate_finding_append_only BEFORE UPDATE OR DELETE ON ai_vendor_invoice_near_duplicate_finding FOR EACH ROW EXECUTE FUNCTION reject_mutation();CREATE TRIGGER ai_vendor_invoice_near_duplicate_source_append_only BEFORE UPDATE OR DELETE ON ai_vendor_invoice_near_duplicate_source FOR EACH ROW EXECUTE FUNCTION reject_mutation();
CREATE FUNCTION refs_ai_vendor_invoice_near_duplicate_batch_hash(p_tenant uuid,p_entity uuid,p_period uuid,p_batch jsonb) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=pg_catalog,public,pg_temp AS $$SELECT refs_jsonb_hash(jsonb_build_object('schema_version','AI_VENDOR_INVOICE_NEAR_DUPLICATE_RUN_V1','tenant_id',p_tenant,'entity_id',p_entity,'accounting_period_id',p_period,'batch',p_batch))$$;
CREATE FUNCTION refs_materialize_ai_vendor_invoice_near_duplicate_batch(p_tenant uuid,p_entity uuid,p_period uuid,p_batch jsonb,p_idempotency_key text,p_request_hash text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE actor text:=refs_current_actor();idem idempotency_receipt;item jsonb;trace jsonb;first_trace jsonb;second_trace jsonb;retained wbs_final1_retained_source_row;source source_document;source_line source_document_line;approved_policy jsonb;finding_id uuid;finding_hash text;event_payload jsonb;response jsonb;inserted_count integer:=0;replay_count integer:=0;result_ids jsonb:='[]'::jsonb;trace_count integer;ordinal integer;computed_amount_variance numeric(20,4);computed_variance_bps integer;computed_date_gap integer;
BEGIN
  PERFORM refs_assert_ai_analysis_scope(p_tenant,p_entity);IF actor IS NULL THEN RAISE EXCEPTION 'Authenticated vendor near-duplicate actor missing' USING ERRCODE='42501';END IF;IF length(coalesce(p_idempotency_key,'')) NOT BETWEEN 8 AND 200 THEN RAISE EXCEPTION 'Vendor near-duplicate idempotency key is invalid' USING ERRCODE='22023';END IF;
  IF p_request_hash IS DISTINCT FROM refs_ai_vendor_invoice_near_duplicate_batch_hash(p_tenant,p_entity,p_period,p_batch) THEN RAISE EXCEPTION 'Vendor near-duplicate request hash is not canonical' USING ERRCODE='22023';END IF;
  IF jsonb_typeof(p_batch)<>'object' OR (p_batch-'schema_version'-'current_accounting_period_id'-'scanned_line_count'-'finding_count'-'findings'-'action_flags')<>'{}'::jsonb OR p_batch->>'schema_version'<>'AI_VENDOR_INVOICE_NEAR_DUPLICATE_BATCH_V1' OR p_batch->>'current_accounting_period_id'<>p_period::text OR jsonb_typeof(p_batch->'findings')<>'array' OR jsonb_array_length(p_batch->'findings')>500 OR (p_batch->>'finding_count')::integer<>jsonb_array_length(p_batch->'findings') OR p_batch->'action_flags' IS DISTINCT FROM '{"can_create_draft":false,"can_review":false,"can_approve":false,"can_post":false}'::jsonb THEN RAISE EXCEPTION 'Vendor near-duplicate batch is malformed or action-enabled' USING ERRCODE='22023';END IF;
  INSERT INTO idempotency_receipt(tenant_id,operation_scope,idempotency_key,request_hash,status,actor_id) VALUES(p_tenant,'AI_VENDOR_INVOICE_NEAR_DUPLICATE:'||p_entity||':'||p_period,p_idempotency_key,p_request_hash,'IN_PROGRESS',actor) ON CONFLICT(tenant_id,operation_scope,idempotency_key) DO NOTHING;
  SELECT * INTO idem FROM idempotency_receipt WHERE tenant_id=p_tenant AND operation_scope='AI_VENDOR_INVOICE_NEAR_DUPLICATE:'||p_entity||':'||p_period AND idempotency_key=p_idempotency_key FOR UPDATE;
  IF idem.request_hash IS DISTINCT FROM p_request_hash OR idem.actor_id IS DISTINCT FROM actor THEN RAISE EXCEPTION 'Vendor near-duplicate idempotency key conflicts with payload or actor' USING ERRCODE='23505';END IF;IF idem.status='SUCCEEDED' THEN RETURN idem.response_body||jsonb_build_object('idempotent',true);END IF;
  approved_policy:=refs_read_ai_vendor_invoice_near_duplicate_policy(p_tenant,p_entity,p_period);IF approved_policy IS NULL THEN RAISE EXCEPTION 'Approved vendor near-duplicate policy is required' USING ERRCODE='23514';END IF;
  FOR item IN SELECT value FROM jsonb_array_elements(p_batch->'findings') LOOP
    IF (item-'schema_version'-'finding_type'-'risk_level'-'rule_id'-'entity_id'-'accounting_period_ids'-'vendor_ref'-'vendor_name'-'currency'-'project_ref'-'property_ref'-'normalized_invoice_number'-'amount_variance'-'amount_variance_basis_points'-'date_gap_days'-'reason'-'suggested_action'-'confidence'-'owner_role'-'due_basis'-'required_human_fields'-'source_trace'-'policy_evidence'-'action_flags')<>'{}'::jsonb OR item->>'schema_version'<>'AI_VENDOR_INVOICE_NEAR_DUPLICATE_FINDING_V1' OR item->>'finding_type'<>'VENDOR_INVOICE_NEAR_DUPLICATE' OR item->>'rule_id'<>'AI_VENDOR_INVOICE_NORMALIZED_ID_AMOUNT_DATE_V1' OR item->>'risk_level' NOT IN('HIGH','MEDIUM') OR item->>'entity_id'<>p_entity::text OR jsonb_typeof(item->'accounting_period_ids')<>'array' OR jsonb_array_length(item->'accounting_period_ids') NOT BETWEEN 1 AND 2 OR NOT(item->'accounting_period_ids' ? p_period::text) OR item->>'normalized_invoice_number'!~'^[A-Z0-9]{4,200}$' OR item->>'amount_variance'!~'^(0|[1-9][0-9]*)\.[0-9]{4}$' OR jsonb_typeof(item->'amount_variance_basis_points')<>'number' OR (item->>'amount_variance_basis_points')::integer NOT BETWEEN 0 AND 1000 OR jsonb_typeof(item->'date_gap_days')<>'number' OR (item->>'date_gap_days')::integer NOT BETWEEN 0 AND 31 OR item->'required_human_fields' IS DISTINCT FROM '["duplicate_determination","source_document_comparison","goods_or_services_received","payment_status","resolution_reason"]'::jsonb OR item->>'owner_role'<>'CONTROLLER_REVIEW' OR item->>'due_basis'<>'BEFORE_PAYMENT_OR_PERIOD_CLOSE' OR item->'policy_evidence' IS DISTINCT FROM approved_policy OR item->'action_flags' IS DISTINCT FROM '{"can_create_draft":false,"can_review":false,"can_approve":false,"can_post":false}'::jsonb OR jsonb_typeof(item->'source_trace')<>'array' OR jsonb_array_length(item->'source_trace')<>2 THEN RAISE EXCEPTION 'Vendor near-duplicate finding is malformed, unscoped, policy-drifted, or action-enabled' USING ERRCODE='22023';END IF;
    trace_count:=0;ordinal:=0;
    FOR trace IN SELECT value FROM jsonb_array_elements(item->'source_trace') LOOP ordinal:=ordinal+1;
      IF (trace-'source_document_id'-'source_document_line_id'-'source_payload_hash'-'source_line_hash'-'accounting_period_id'-'invoice_number'-'invoice_date'-'amount')<>'{}'::jsonb OR trace->>'source_document_id'!~'^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' OR trace->>'source_document_line_id'!~'^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' OR trace->>'source_payload_hash'!~'^sha256:[0-9a-f]{64}$' OR trace->>'source_line_hash'!~'^sha256:[0-9a-f]{64}$' OR trace->>'accounting_period_id'!~'^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' OR length(btrim(coalesce(trace->>'invoice_number',''))) NOT BETWEEN 1 AND 200 OR trace->>'invoice_date'!~'^\d{4}-\d{2}-\d{2}$' OR trace->>'amount'!~'^(0|[1-9][0-9]*)\.[0-9]{4}$' THEN RAISE EXCEPTION 'Vendor near-duplicate source trace is malformed' USING ERRCODE='22023';END IF;
      SELECT * INTO retained FROM wbs_final1_retained_source_row r WHERE r.tenant_id=p_tenant AND r.entity_id=p_entity AND r.domain='PAYABLES' AND r.source_document_id=(trace->>'source_document_id')::uuid AND r.source_document_line_id=(trace->>'source_document_line_id')::uuid AND r.accounting_period_id=(trace->>'accounting_period_id')::uuid AND r.raw_row_hash=trace->>'source_line_hash' FOR SHARE;IF NOT FOUND THEN RAISE EXCEPTION 'Vendor near-duplicate trace is not exact retained payable evidence' USING ERRCODE='23514';END IF;
      SELECT * INTO source FROM source_document d WHERE d.tenant_id=p_tenant AND d.entity_id=p_entity AND d.source_document_id=retained.source_document_id AND d.payload_hash=trace->>'source_payload_hash' FOR SHARE;IF NOT FOUND THEN RAISE EXCEPTION 'Vendor near-duplicate source lineage changed' USING ERRCODE='23514';END IF;
      SELECT * INTO source_line FROM source_document_line l WHERE l.tenant_id=p_tenant AND l.entity_id=p_entity AND l.source_document_id=retained.source_document_id AND l.source_document_line_id=retained.source_document_line_id FOR SHARE;IF NOT FOUND OR source.document_no IS DISTINCT FROM trace->>'invoice_number' OR source.currency IS DISTINCT FROM item->>'currency' OR source_line.amount IS DISTINCT FROM (trace->>'amount')::numeric OR source_line.external_dimension_refs->>'signed_invoice_date' IS DISTINCT FROM trace->>'invoice_date' OR source_line.party_ref IS DISTINCT FROM item->>'vendor_ref' OR source_line.project_ref IS DISTINCT FROM nullif(item->>'project_ref','') OR source_line.property_ref IS DISTINCT FROM nullif(item->>'property_ref','') THEN RAISE EXCEPTION 'Vendor near-duplicate trace fields do not match retained signed source detail' USING ERRCODE='23514';END IF;
      IF ordinal=1 THEN first_trace:=trace;ELSE second_trace:=trace;END IF;trace_count:=trace_count+1;
    END LOOP;
    IF trace_count<>2 OR first_trace->>'source_document_id'=second_trace->>'source_document_id' OR first_trace->>'source_document_line_id'=second_trace->>'source_document_line_id' OR upper(btrim(first_trace->>'invoice_number'))=upper(btrim(second_trace->>'invoice_number')) OR regexp_replace(upper(first_trace->>'invoice_number'),'[^A-Z0-9]','','g') IS DISTINCT FROM item->>'normalized_invoice_number' OR regexp_replace(upper(second_trace->>'invoice_number'),'[^A-Z0-9]','','g') IS DISTINCT FROM item->>'normalized_invoice_number' THEN RAISE EXCEPTION 'Vendor near-duplicate requires two distinct exact source lines with one normalized invoice identity' USING ERRCODE='23514';END IF;
    IF EXISTS(SELECT 1 FROM jsonb_array_elements_text(item->'accounting_period_ids') period_id WHERE period_id NOT IN(first_trace->>'accounting_period_id',second_trace->>'accounting_period_id')) OR NOT(item->'accounting_period_ids' ? (first_trace->>'accounting_period_id')) OR NOT(item->'accounting_period_ids' ? (second_trace->>'accounting_period_id')) THEN RAISE EXCEPTION 'Vendor near-duplicate accounting periods do not exactly match both sources' USING ERRCODE='23514';END IF;
    computed_amount_variance:=abs((first_trace->>'amount')::numeric-(second_trace->>'amount')::numeric);computed_variance_bps:=floor(computed_amount_variance*10000/greatest((first_trace->>'amount')::numeric,(second_trace->>'amount')::numeric));computed_date_gap:=abs((first_trace->>'invoice_date')::date-(second_trace->>'invoice_date')::date);
    IF (item->>'amount_variance')::numeric IS DISTINCT FROM computed_amount_variance OR (item->>'amount_variance_basis_points')::integer IS DISTINCT FROM computed_variance_bps OR (item->>'date_gap_days')::integer IS DISTINCT FROM computed_date_gap OR computed_amount_variance>(approved_policy->>'maximum_absolute_amount_variance')::numeric OR computed_variance_bps>(approved_policy->>'maximum_amount_variance_basis_points')::integer OR computed_date_gap>(approved_policy->>'maximum_date_gap_days')::integer OR item->>'risk_level' IS DISTINCT FROM (CASE WHEN computed_amount_variance=0 THEN 'HIGH' ELSE 'MEDIUM' END) THEN RAISE EXCEPTION 'Vendor near-duplicate comparison was not reproducible under approved policy' USING ERRCODE='23514';END IF;
    finding_hash:=refs_jsonb_hash(jsonb_build_object('schema_version','AI_VENDOR_INVOICE_NEAR_DUPLICATE_EVIDENCE_V1','tenant_id',p_tenant,'entity_id',p_entity,'accounting_period_id',p_period,'finding',item));SELECT ai_vendor_invoice_near_duplicate_finding_id INTO finding_id FROM ai_vendor_invoice_near_duplicate_finding WHERE tenant_id=p_tenant AND entity_id=p_entity AND finding_hash=finding_hash;
    IF FOUND THEN replay_count:=replay_count+1;ELSE finding_id:=gen_random_uuid();INSERT INTO ai_vendor_invoice_near_duplicate_finding(ai_vendor_invoice_near_duplicate_finding_id,tenant_id,entity_id,accounting_period_id,policy_snapshot_id,policy_snapshot_hash,finding_hash,finding,created_by) VALUES(finding_id,p_tenant,p_entity,p_period,(item#>>'{policy_evidence,setting_snapshot_id}')::uuid,item#>>'{policy_evidence,setting_snapshot_hash}',finding_hash,item,actor);
      ordinal:=0;FOR trace IN SELECT value FROM jsonb_array_elements(item->'source_trace') LOOP ordinal:=ordinal+1;INSERT INTO ai_vendor_invoice_near_duplicate_source(tenant_id,entity_id,ai_vendor_invoice_near_duplicate_finding_id,source_ordinal,accounting_period_id,source_document_id,source_document_line_id,source_payload_hash,source_line_hash) VALUES(p_tenant,p_entity,finding_id,ordinal,(trace->>'accounting_period_id')::uuid,(trace->>'source_document_id')::uuid,(trace->>'source_document_line_id')::uuid,trace->>'source_payload_hash',trace->>'source_line_hash');END LOOP;
      event_payload:=jsonb_build_object('schema_version','AI_VENDOR_INVOICE_NEAR_DUPLICATE_EVIDENCE_V1','finding_id',finding_id,'finding_hash',finding_hash,'source_trace_hash',refs_jsonb_hash(item->'source_trace'),'policy_snapshot_id',item#>>'{policy_evidence,setting_snapshot_id}','policy_snapshot_hash',item#>>'{policy_evidence,setting_snapshot_hash}','duplicate_determination','HUMAN_DECISION_REQUIRED','can_create_draft',false,'can_review',false,'can_approve',false,'can_post',false);
      INSERT INTO audit_event(tenant_id,entity_id,event_type,object_type,object_id,action,actor_id,actor_type,permission_used,request_id,correlation_id,idempotency_key,after_hash,reason,metadata) VALUES(p_tenant,p_entity,'AI_VENDOR_INVOICE_NEAR_DUPLICATE_MATERIALIZED','AI_VENDOR_INVOICE_NEAR_DUPLICATE_FINDING',finding_id,'MATERIALIZE',actor,'USER','AI.ANALYSIS.EXPLAIN',p_idempotency_key,p_idempotency_key,p_idempotency_key,finding_hash,'Deterministic source-bound near-duplicate invoice evidence; resolution requires human review',event_payload);
      INSERT INTO outbox_event(tenant_id,entity_id,aggregate_type,aggregate_id,event_type,payload,payload_hash) VALUES(p_tenant,p_entity,'AI_VENDOR_INVOICE_NEAR_DUPLICATE_FINDING',finding_id,'AI_VENDOR_INVOICE_NEAR_DUPLICATE_MATERIALIZED',event_payload,refs_jsonb_hash(event_payload));inserted_count:=inserted_count+1;END IF;result_ids:=result_ids||jsonb_build_array(finding_id);
  END LOOP;
  response:=jsonb_build_object('schema_version','AI_VENDOR_INVOICE_NEAR_DUPLICATE_RUN_RECEIPT_V1','accounting_period_id',p_period,'row_count',jsonb_array_length(p_batch->'findings'),'inserted_count',inserted_count,'replayed_count',replay_count,'finding_ids',result_ids,'request_hash',p_request_hash,'can_create_draft',false,'can_review',false,'can_approve',false,'can_post',false,'idempotent',false);UPDATE idempotency_receipt SET status='SUCCEEDED',response_status=201,response_body=response,completed_at=clock_timestamp() WHERE idempotency_receipt_id=idem.idempotency_receipt_id;RETURN response;
END;$$;
REVOKE ALL ON ai_vendor_invoice_near_duplicate_finding,ai_vendor_invoice_near_duplicate_source FROM PUBLIC,refs_app;REVOKE ALL ON FUNCTION refs_ai_vendor_invoice_near_duplicate_batch_hash(uuid,uuid,uuid,jsonb),refs_materialize_ai_vendor_invoice_near_duplicate_batch(uuid,uuid,uuid,jsonb,text,text) FROM PUBLIC;GRANT EXECUTE ON FUNCTION refs_ai_vendor_invoice_near_duplicate_batch_hash(uuid,uuid,uuid,jsonb),refs_materialize_ai_vendor_invoice_near_duplicate_batch(uuid,uuid,uuid,jsonb,text,text) TO refs_app;
COMMIT;
